function [ceq c] = cr1(f,t_ult,t_out,u,y,stages)
k10  = 4    ;
k20 = 800   ;
E1 = 6e3    ;
R = 8.31    ;
dH1 = -3e4  ;
dH2 = -1e4  ;
qr_maf=1.5e5;
V_maf=1.1   ;
E2 = 2e4    ;
cb_in = 20  ;

timeL=0;

%equality
ceq = [];

timeL=0;

%inequality
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = -dH1*y(time,1)*f(time,1)*f(time,2)*f(time,4) -dH2*y(time,2)*f(time,3)*f(time,4) - qr_maf;
end
timeL=length(f(:,1));;
c(2) = f(end,4) - V_maf                                                                        ;


end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
